cat > /tmp/blocks.php <<'EOF'
<?php
$active = \Drupal::configFactory()->listAll('block.block');
sort($active);
echo "DB block configs: " . count($active) . PHP_EOL;
echo implode("\n", array_slice($active,0,15)) . "\n...\n";
$storage = new \Drupal\Core\Config\FileStorage(\Drupal::root() . '/../config/sync');
$sync = $storage->listAll('block.block');
sort($sync);
echo "SYNC block configs: " . count($sync) . PHP_EOL;
echo implode("\n", array_slice($sync,0,15)) . "\n";
echo "in DB not sync:\n" . implode("\n", array_slice(array_diff($active,$sync),0,20)) . "\n";
echo "in sync not DB:\n" . implode("\n", array_slice(array_diff($sync,$active),0,20)) . "\n";
EOF
cd /workspace && cp /tmp/blocks.php /workspace/blocks_tmp.php && su ddevuser -c "ddev drush php:script blocks_tmp.php" 2>&1 | tail -70; rm -f /workspace/blocks_tmp.php
